#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> arr(n);
    for (int i = 0; i < n; ++i) {
        cin >> arr[i];
    }

    vector<int> arr_mod(n);
    for (int i = 0; i < n; ++i) {
        arr_mod[i] = arr[i] % k;
    }

    if (n == 1) {
        cout << arr_mod[0] << "\n";
        return 0;
    }

    vector<int> part1(arr_mod.begin(), arr_mod.begin() + n / 2);
    vector<int> part2(arr_mod.begin() + n / 2, arr_mod.end());

    std::set<int> setA, setB, temp_setB;

    for (int val : part1) {
        for (int prev : setA) {
            setB.insert((prev + val) % k);
        }
        setA.insert(val);
        for (int prev : setB) {
            setA.insert(prev);
        }
        setB.clear();
    }

    for (int val : part2) {
        for (int prev : setB) {
            setB.insert((prev + val) % k);
        }
        for (int prev : setA) {
            setB.insert(prev);
        }
    }

    std::vector<int> list_s(setA.begin(), setA.end());
    std::vector<int> list_s1(setB.begin(), setB.end());

    int max_value = 0;
    if (!list_s.empty()) max_value = std::max(max_value, *max_element(list_s.begin(), list_s.end()));
    if (!list_s1.empty()) max_value = std::max(max_value, *max_element(list_s1.begin(), list_s1.end()));

    int res = max_value;

    for (int s_elem : list_s) {
        int target = k - 1 - s_elem;
        auto it = std::upper_bound(list_s1.begin(), list_s1.end(), target);
        if (it != list_s1.begin()) {
            int r = *(it - 1);
            int rt = list_s1.back();
            int candidate1 = (r + s_elem) % k;
            int candidate2 = (s_elem + rt) % k;
            res = std::max(res, std::max(candidate1, candidate2));
        }
    }

    cout << res << "\n";

    return 0;
}
